insert into public.content_translations (content_type, content_id, language, field, value, status) values
  ('culture_item', 'oymo-overview', 'ru', 'title', 'Кыргызские орнаменты (оймо)', 'reviewed'),
  ('culture_item', 'oymo-overview', 'ru', 'origin', 'Оюм (оймо) — узор, рисунок и форма, которые используются во всех видах кыргызского декоративно-прикладного искусства.', 'reviewed'),
  ('culture_item', 'oymo-overview', 'ru', 'history', 'Кыргызские женщины создавали множество вариаций одного и того же мотива и внесли большой вклад в развитие и разнообразие этих узоров.', 'reviewed'),
  ('culture_item', 'oymo-overview', 'ru', 'cultural_meaning', 'Каждый узор имеет своё значение: «мүйүз» (рог скота), «карга тырмак» (воронья лапка), «кыял» (формы, рождённые воображением), «жалбырак» (лист), «гүл» (цветок), а также образы природы — солнце, луна, вода — несут символический смысл.', 'reviewed'),
  ('culture_item', 'oymo-overview', 'ru', 'objects_used', 'Войлок (ала кийиз, шырдак, туш кийиз), кожаные изделия (көөкөр, көнөк, тердик), деревянные предметы, украшения из серебра и меди, вышивка.', 'reviewed'),
  ('culture_item', 'oymo-overview', 'ru', 'fun_facts', 'Оймо — это не только украшение: каждый элемент рассматривается как знак со своим смыслом в целой системе символов.', 'reviewed'),
  ('culture_item', 'shyrdak-craft', 'ru', 'title', 'Шырдак', 'reviewed'),
  ('culture_item', 'shyrdak-craft', 'ru', 'alt_names', 'Шырымал, төрбөлжүн, оймо теке, ободо, түр кийиз (региональные названия)', 'reviewed'),
  ('culture_item', 'shyrdak-craft', 'ru', 'origin', 'Одно из войлочных изделий кыргызов и монголов с самой сложной технологией изготовления; по-монгольски называется «ширдэг».', 'reviewed'),
  ('culture_item', 'shyrdak-craft', 'ru', 'history', 'В 2012 году традиционное кыргызское искусство изготовления шырдака и ала кийиза было включено в список нематериального культурного наследия ЮНЕСКО.', 'reviewed'),
  ('culture_item', 'shyrdak-craft', 'ru', 'traditional_method', 'Стандартный размер — 2×4 метра. Два слоя войлока контрастных цветов кладут друг на друга, наносят узор и одновременно разрезают их острым инструментом; затем вырезанные части меняют местами и сшивают между собой — получается позитивно-негативный рисунок. Технику шитья называют «шырык», отсюда и название «шырдак».', 'reviewed'),
  ('culture_item', 'shyrdak-craft', 'ru', 'modern_status', 'Сегодня вместо натуральных красителей (уу тамыры, индиго, испарак) используют анилиновые.', 'reviewed'),
  ('culture_item', 'shyrdak-craft', 'ru', 'fun_facts', 'Узоры чаще всего изображают части животных: собачий хвост, рога горного козла, птичьи когти. Края обязательно завершаются белым и чёрным цветами — это означает заснеженные вершины кыргызских гор. Шырдак из хорошего войлока при правильном хранении может служить до ста лет.', 'reviewed'),
  ('culture_item', 'boz-uy-overview', 'ru', 'title', 'Боз үй', 'reviewed'),
  ('culture_item', 'boz-uy-overview', 'ru', 'origin', 'Жилище, возникшее из древнего кочевого быта: оно легко собирается и разбирается и перевозится на вьюках.', 'reviewed'),
  ('culture_item', 'boz-uy-overview', 'ru', 'history', 'Основное традиционное жилище кыргызов — кочевое жилище с деревянным каркасом, покрытым войлоком. Его форма веками оставалась неизменной.', 'reviewed'),
  ('culture_item', 'boz-uy-overview', 'ru', 'cultural_meaning', 'Түндүк — символ национальной идентичности кыргызов: его изображение помещено на государственный флаг Кыргызстана.', 'reviewed'),
  ('culture_item', 'boz-uy-overview', 'ru', 'traditional_method', 'Сборка идёт по порядку: сначала раскладывают и устанавливают кереге, затем уук привязывают к верхнему краю кереге заострённым концом, с помощью шестов поднимают түндүк и вставляют в него концы уук, после этого навешивают чий, войлочные покрытия и дверь.', 'reviewed'),
  ('culture_item', 'boz-uy-overview', 'ru', 'objects_used', 'Кереге (каркас стен), уук (шесты купола), түндүк (верхний круг купола), босого (дверная рама), каалга (дверь).', 'reviewed'),
  ('culture_item', 'oymo-umai-ene', 'ru', 'title', 'Умай эне', 'reviewed'),
  ('culture_item', 'oymo-umai-ene', 'ru', 'origin', 'Умай эне — священная богиня-мать в древних верованиях тюркских народов, покровительница детей и рожениц.', 'reviewed'),
  ('culture_item', 'oymo-umai-ene', 'ru', 'cultural_meaning', 'Узор Умай эне — священный знак тюркских народов, передающий образ древней богини. У кыргызов и других кочевых народов Центральной Азии этот знак означает женское начало, материнское благородство, а также защиту детей и домашнего очага.', 'reviewed'),
  ('culture_item', 'oymo-umai-ene', 'ru', 'fun_facts', 'По традиции этот знак вышивали на детской одежде и головных уборах (например, на детском ак калпаке), веря, что он защищает от болезней и злых сил. Есть и поверье, что улыбка ребёнка во сне означает присутствие Умай эне.', 'reviewed'),
  ('culture_item', 'oymo-kochkor-muyuz', 'ru', 'title', 'Кочкор мүйүз', 'reviewed'),
  ('culture_item', 'oymo-kochkor-muyuz', 'ru', 'cultural_meaning', 'Означает скот хозяина и народа, живущего на джайлоо. Без кочкор мүйүз не создаётся ни один узор. Именно этот элемент отличает кыргызский орнамент от орнаментов других народов.', 'reviewed'),
  ('culture_item', 'oymo-kaz-moyun', 'ru', 'title', 'Каз моюн', 'reviewed'),
  ('culture_item', 'oymo-kaz-moyun', 'ru', 'cultural_meaning', 'Узор, похожий на шею гуся.', 'reviewed'),
  ('culture_item', 'shyrdak-at-bashy', 'ru', 'title', 'Ат-Башы — родина шырдака', 'reviewed'),
  ('culture_item', 'shyrdak-at-bashy', 'ru', 'origin', 'Ат-Башинский район Нарынской области признан родиной искусства шырдака.', 'reviewed'),
  ('culture_item', 'shyrdak-at-bashy', 'ru', 'history', 'Это ремесло, начавшее было забываться, возродилось после признания ЮНЕСКО в 2012 году. В Ат-Башы создано объединение «Алтын казан» (Golden Cauldron Herders), в котором работают около 60–70 опытных мастериц.', 'reviewed'),
  ('culture_item', 'shyrdak-at-bashy', 'ru', 'cultural_meaning', 'Шырдак мастерицы Жаңыйыл из Ат-Башы выставлялся в центральном музее Великобритании — пример международного признания кыргызского шырдака.', 'reviewed'),
  ('culture_item', 'shyrdak-at-bashy', 'ru', 'fun_facts', 'В ежегодном фестивале в Ат-Башы участвовали более 1500 шырдаков и более 500 мастериц; работы-победители получают денежные призы и передаются в национальные музеи.', 'reviewed'),
  ('culture_item', 'horse-overview', 'ru', 'title', 'Конная культура', 'reviewed'),
  ('culture_item', 'horse-overview', 'ru', 'origin', 'Происходит из кочевого быта: для кыргыза конь был не только средством передвижения, но и основой хозяйства, войны, игр и семейных традиций.', 'reviewed'),
  ('culture_item', 'horse-overview', 'ru', 'history', 'Считается, что предки кыргызов начали разводить лошадей около четырёх тысяч лет назад. Веками кочёвки, выход на джайлоо и спуск на зимовки — всё было связано с конём.', 'reviewed'),
  ('culture_item', 'horse-overview', 'ru', 'cultural_meaning', 'Недаром у кыргызов говорят: «Ат — адамдын канаты» («Конь — крылья человека»). Конь — символ богатства, свободы и чести; подарить коня — высший знак уважения.', 'reviewed'),
  ('culture_item', 'horse-overview', 'ru', 'when_used', 'Круглый год: в кочёвках, на джайлоо, на свадьбах, на поминках (аш), в национальных играх.', 'reviewed'),
  ('culture_item', 'horse-overview', 'ru', 'traditional_method', 'Традиция ухода за конём передавалась от отца к сыну: привязывать на аркан, пасти, поить, расчёсывать гриву и хвост, постепенно откармливать — всё делалось в своё время и по своим правилам. Ребёнка начинали сажать на коня в 3–5 лет, а в 5–6 лет он уже ездил самостоятельно.', 'reviewed'),
  ('culture_item', 'horse-overview', 'ru', 'who_participates', 'Вся семья и община; табунщик, наездник, конюх.', 'reviewed'),
  ('culture_item', 'horse-overview', 'ru', 'objects_used', 'Ээр (седло), жүгөн (узда), ооздук (удила), үзөңгү (стремя), көмөлдүрүк (нагрудник), куюшкан (подхвостник), тердик (потник), камчы (плеть).', 'reviewed'),
  ('culture_item', 'horse-overview', 'ru', 'modern_status', 'Разведение лошадей в Кыргызстане продолжается и сегодня; национальные конные игры поддерживаются на государственном уровне и показываются на Всемирных играх кочевников.', 'reviewed'),
  ('culture_item', 'horse-overview', 'ru', 'fun_facts', 'В кыргызском языке сотни названий, связанных с лошадью: в зависимости от возраста, масти, аллюра и нрава для каждой используется отдельное слово.', 'reviewed'),
  ('culture_item', 'horse-jylky', 'ru', 'title', 'Кыргызская лошадь', 'reviewed'),
  ('culture_item', 'horse-jylky', 'ru', 'alt_names', 'Кыргызский конь', 'reviewed'),
  ('culture_item', 'horse-jylky', 'ru', 'origin', 'Порода, происходящая от лошадей древних кыргызов и приспособленная к горно-степным условиям. Сказалось и влияние монгольских и восточных пород.', 'reviewed'),
  ('culture_item', 'horse-jylky', 'ru', 'history', 'В конце XIX века между Уралом и Алтаем было около 4 миллионов кыргызских лошадей. В советское время (с 1930-х годов) их скрещивали с английской и донской породами и вывели «новокыргызскую породу».', 'reviewed'),
  ('culture_item', 'horse-jylky', 'ru', 'cultural_meaning', 'Кыргызская лошадь — животное, которое поддерживало жизнь народа: использовали её мясо, молоко (кымыз), шкуру и силу.', 'reviewed'),
  ('culture_item', 'horse-jylky', 'ru', 'modern_status', 'Порода сохраняется; французские исследователи отмечают кыргызскую лошадь как одну из древнейших пород в мире, ведётся работа по её сохранению.', 'reviewed'),
  ('culture_item', 'horse-jylky', 'ru', 'fun_facts', 'Средний рост — 137 см. Копыта настолько крепкие, что даже в долгом пути ковать их не нужно. Круглый год пасётся на пастбище и зимой может обходиться малым количеством сена. Многие от природы — иноходцы.', 'reviewed'),
  ('culture_item', 'horse-eer', 'ru', 'title', 'Седло и конское снаряжение', 'reviewed'),
  ('culture_item', 'horse-eer', 'ru', 'origin', 'В кочевом быту конское снаряжение было нужно каждый день, поэтому каждая его часть развивалась как отдельное ремесло.', 'reviewed'),
  ('culture_item', 'horse-eer', 'ru', 'history', 'Вырезать седло из дерева, выделывать кожу, инкрустировать серебром — отдельные ремёсла мастеров. Кыргызские сёдла XIX века хранятся в музеях.', 'reviewed'),
  ('culture_item', 'horse-eer', 'ru', 'cultural_meaning', 'Седло — не просто вещь, а предмет, показывающий положение и вкус владельца. Украшенные седло и снаряжение выводили на свадьбу, к почётным гостям и на скачки.', 'reviewed'),
  ('culture_item', 'horse-eer', 'ru', 'when_used', 'Каждый день при верховой езде, а также на свадьбах, скачках и в почётных подарках.', 'reviewed'),
  ('culture_item', 'horse-eer', 'ru', 'traditional_method', 'Каркас седла вырезают из дерева и обтягивают кожей; наносят узор и украшают серебром или медью. Тердик кладут между конём и седлом, чтобы защитить спину коня.', 'reviewed'),
  ('culture_item', 'horse-eer', 'ru', 'objects_used', 'Ээр (деревянный каркас седла), тердик (потник), көпчүк (подушка седла), үзөңгү (стремя), жүгөн (узда), ооздук (удила), чылбыр (повод), көмөлдүрүк (нагрудник), куюшкан (подхвостник), камчы (плеть).', 'reviewed'),
  ('culture_item', 'horse-eer', 'ru', 'modern_status', 'Традиционное ремесло изготовления седла сохраняется благодаря мастерам; оно широко используется в национальных играх и на этнофестивалях.', 'reviewed'),
  ('culture_item', 'horse-eer', 'ru', 'fun_facts', 'Украшенное седло с полным снаряжением раньше давали и в приданое, провожая дочь замуж.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'ru', 'title', 'Кок бору', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'ru', 'alt_names', 'Улак тартыш', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'ru', 'origin', 'По записям этнографа Г. Н. Симакова: кыргызы, настигнув на быстром коне волка в глубоком снегу, затем в шутку отбирали друг у друга тушу волка — так сложилась игра.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'ru', 'history', 'Современные единые правила разработал в 1996 году кинорежиссёр Болот Шамшиев. 9 ноября 2001 года в Бишкеке была создана Международная федерация кок бору. В декабре 2017 года игра была включена в список нематериального культурного наследия ЮНЕСКО.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'ru', 'cultural_meaning', 'Кок бору — символ отваги, выносливости и командного единства. Игра, в которой единство коня и человека видно ярче всего.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'ru', 'when_used', 'На свадьбах, поминках (аш), национальных праздниках, на Всемирных играх кочевников.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'ru', 'traditional_method', 'Поле — 200×70 метров, по краям стоят круглые ворота, которые называются «тай казан». В каждой команде 8–12 наездников, одновременно играют по четыре. Игра состоит из трёх таймов по 20 минут. Нужно подхватить улак с земли или отобрать у соперника и положить в тай казан своей команды. Запрещено бить рукой, ногой или камчой, хватать за повод и поднимать коня на дыбы.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'ru', 'who_participates', 'Наездники двух команд; судьи и жители айыла как зрители.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'ru', 'objects_used', 'Улак (туша козлёнка или козла), конь, седло с снаряжением, тай казан.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'ru', 'modern_status', 'Национальный вид спорта Кыргызстана; на Всемирных играх кочевников Кыргызстан становился чемпионом в 2014, 2016, 2018, 2022 и 2024 годах.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'ru', 'fun_facts', 'После игры из мяса улака готовят куурдак; в народе сохраняется поверье, что «в этом мясе есть исцеление».', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'ru', 'title', 'Ат чабыш', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'ru', 'origin', 'Древнейшие скачки кочевого быта, испытывающие силу и выносливость коня.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'ru', 'history', 'Ат чабыш всегда был одной из главных частей свадьбы и поминок (аш); на больших поминках лучшим призом был скот «тогуз тогуз» — девять раз по девять голов.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'ru', 'cultural_meaning', 'Ат чабыш — честь семьи и рода. И владельца коня, взявшего приз, и его наездника прославляют в народе.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'ru', 'when_used', 'На свадьбах, поминках (аш), национальных праздниках.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'ru', 'traditional_method', 'Дистанция — от 1200 метров до 50 километров. Наездники — чаще всего лёгкие мальчики 8–14 лет. К торжеству коня специально «тапка келтирет» (готовят): сгоняют лишний жир, доводят до потовыделения и закаляют. Побеждает конь, первым пришедший к финишу.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'ru', 'who_participates', 'Мальчики-наездники; владелец коня, конюх и вся община.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'ru', 'objects_used', 'Скаковой конь, лёгкое седло, камча.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'ru', 'modern_status', 'Проводится и сегодня на ипподромах и сельских праздниках; правила безопасности ужесточены, от наездников требуют шлем и защитную одежду.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'ru', 'fun_facts', 'Многомесячную подготовку коня к скачкам называют «ат тапка келтирүү» — это ценится как отдельное искусство.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'ru', 'title', 'Кыз куумай', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'ru', 'origin', 'Конная игра, выросшая из традиции знакомства и состязания молодёжи.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'ru', 'history', 'Издавна проводилась на свадьбах; сегодня входит в классификацию национальных видов спорта.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'ru', 'cultural_meaning', 'Кыз куумай — игра, которая показывает и мастерство девушки в верховой езде: кыргызская девушка должна была быть наездницей не хуже юноши.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'ru', 'when_used', 'На свадьбах, национальных праздниках, народных гуляниях.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'ru', 'traditional_method', 'Девушка и юноша стартуют от отмеченной черты. Девушка скачет впереди, юноша пытается её догнать. Если догонит — побеждает; если не сумеет, то на обратном пути девушка гонит его, стегая камчой.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'ru', 'who_participates', 'Девушка и юноша; вся община как зрители.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'ru', 'objects_used', 'Два коня, камча.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'ru', 'modern_status', 'Показывается как национальная игра на фестивалях и Всемирных играх кочевников.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'ru', 'title', 'Оодарыш', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'ru', 'alt_names', 'Эңиш', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'ru', 'origin', 'Считается, что произошёл из воинской подготовки: всадник учился сбрасывать противника с седла.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'ru', 'history', 'Одна из древних кыргызских игр; сегодня официальный национальный вид спорта.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'ru', 'cultural_meaning', 'Оодарыш проверяет не только силу, но и единство коня и человека, а также умение держать равновесие.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'ru', 'when_used', 'На свадьбах, поминках (аш), национальных праздниках.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'ru', 'traditional_method', 'Два всадника борются верхом, пытаясь стащить соперника с седла. Запрещены удары, удары по коню и некоторые захваты; есть деление по времени и весовым категориям.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'ru', 'who_participates', 'Двое мужчин-борцов; судьи и зрители.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'ru', 'objects_used', 'Конь, седло со снаряжением, защитная одежда.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'ru', 'modern_status', 'Входит в классификацию национальных видов спорта; есть в программе Всемирных игр кочевников.', 'reviewed'),
  ('culture_item', 'shyrdak-tustor', 'ru', 'title', 'Значение цветов в шырдаке', 'reviewed'),
  ('culture_item', 'shyrdak-tustor', 'ru', 'cultural_meaning', 'Белый — знак чистоты, святости и счастья; связан с младенцами и стариками. Красный — знак крови, силы, счастья, судьбы, любви и огня; означает расцвет жизни (примерно возраст 40 лет) и часто в сочетании с зелёным передаёт изобилие лета. Синий — священный цвет Тенгри, означает небо и космос. Жёлтый означает богатство, власть и далёкую степь, но отдельно не используется — поскольку связан и с понятием болезни и увядания, им чаще обозначают край узора. Зелёный означает молодость и лето, встречается в узорах листьев и ветвей. Чёрный означает землю, силу и честь, но в традиционном понимании чаще связан с отрицательным смыслом (горе, изъян, бедность); в положительном смысле использовался лишь при описании красоты — глаз, волос.', 'reviewed'),
  ('culture_item', 'shyrdak-tustor', 'ru', 'fun_facts', 'Мастерицы выбирали цвета для шырдака не случайно, а с символическим смыслом: каждое сочетание цветов отражало определённое время года или этап жизни.', 'reviewed'),
  ('culture_item', 'boz-uy-tunduk', 'ru', 'title', 'Түндүк', 'reviewed'),
  ('culture_item', 'boz-uy-tunduk', 'ru', 'cultural_meaning', 'Круглое дымовое отверстие в верхней части купола боз үй — самая священная часть дома. Состоит из двух частей: алкак (внешний обод) и чамгарак (переплетённая решётка внутри алкака). В алкаке в зависимости от размера дома 60, 70 или 80 отверстий, в них вставляют и закрепляют концы уук.', 'reviewed'),
  ('culture_item', 'boz-uy-tunduk', 'ru', 'traditional_method', 'Алкак делают из толстой ивы или берёзы: дерево распаривают, сгибают и подгоняют по размеру; две части собирают, накладывая одну на другую.', 'reviewed'),
  ('culture_item', 'boz-uy-tunduk', 'ru', 'modern_status', 'В центре государственного флага Кыргызстана изображён түндүк — один из самых узнаваемых символов национальной идентичности.', 'reviewed'),
  ('culture_item', 'boz-uy-tunduk', 'ru', 'fun_facts', 'Сохранились проклятия и благословения, связанные с түндүком: как дурное пожелание говорили «түндүгүң түшсүн» («пусть рухнет твой түндүк» — пусть распадётся твоя семья), а как благословение — «түндүгүңдөн түтүн үзүлбөсүн» («пусть не прекращается дым из твоего түндүка» — пусть твой род продолжается вечно).', 'reviewed'),
  ('culture_item', 'boz-uy-karkas', 'ru', 'title', 'Деревянный каркас', 'reviewed'),
  ('culture_item', 'boz-uy-karkas', 'ru', 'alt_names', 'Кереге, уук', 'reviewed'),
  ('culture_item', 'boz-uy-karkas', 'ru', 'cultural_meaning', 'Деревянный каркас боз үй состоит из трёх основных частей: кереге (решётчатый каркас, служащий стеной), уук (шесты купола, идущие от кереге к түндүку) и түндүк. Кереге устроен сложнее: дерево распаривают и сгибают, планки располагают на расстоянии 18–20 см и связывают в решётку полосками выделанной кожи (көк); узлы, соединяющие части, называют «саканак». Уук тоже распаривают, точно отмеряют длину и заостряют конец так, чтобы он точно входил в отверстие түндүка.', 'reviewed'),
  ('culture_item', 'boz-uy-karkas', 'ru', 'traditional_method', 'Опытные мастера собирали этот деревянный каркас примерно за 25 дней; готовый каркас, несмотря на постоянные кочёвки, может служить около 25 лет.', 'reviewed'),
  ('culture_item', 'boz-uy-karkas', 'ru', 'objects_used', 'Кереге (каркас стен), уук (шесты купола), түндүк, босого (дверная рама).', 'reviewed'),
  ('culture_item', 'boz-uy-kiyiz-jabuu', 'ru', 'title', 'Войлочные покрытия', 'reviewed'),
  ('culture_item', 'boz-uy-kiyiz-jabuu', 'ru', 'alt_names', 'Туурдук, үзүк', 'reviewed'),
  ('culture_item', 'boz-uy-kiyiz-jabuu', 'ru', 'cultural_meaning', 'Когда деревянный каркас готов, его покрывают войлоком: туурдук (войлок, покрывающий кереге; «жабык башы» обращён внутрь), үзүк (большие передние и задние части — у түндүка «узкая» часть сохраняет прохладу, а нижняя «широкая» приспособлена к весенне-летней жаре), а также войлок для двери и для түндүка. Края этих войлоков украшают вышивкой.', 'reviewed'),
  ('culture_item', 'boz-uy-kiyiz-jabuu', 'ru', 'when_used', 'При кочёвках — каждый раз, когда дом ставят заново на новой стоянке.', 'reviewed'),
  ('culture_item', 'boz-uy-kiyiz-jabuu', 'ru', 'traditional_method', 'Покрытие войлоком требует совместных усилий нескольких человек — чаще этим занимались женщины.', 'reviewed'),
  ('culture_item', 'boz-uy-kiyiz-jabuu', 'ru', 'objects_used', 'Войлок, свалянный из овечьей шерсти, чий (циновка из стеблей чия для обшивки стен).', 'reviewed'),
  ('culture_item', 'boz-uy-ichki-jasalga', 'ru', 'title', 'Внутреннее убранство', 'reviewed'),
  ('culture_item', 'boz-uy-ichki-jasalga', 'ru', 'cultural_meaning', 'Пространство боз үй делится по строгим правилам: левая сторона (мужская половина) — место, где хранятся седло с упряжью и охотничье снаряжение; правая сторона (женская половина) — кухня и рабочее место женщин; в центре — очаг и сундуки рядом; а самое почётное место за очагом называется «төр» и отводится главе семьи или уважаемому гостю.', 'reviewed'),
  ('culture_item', 'boz-uy-ichki-jasalga', 'ru', 'objects_used', 'Туш кийиз (украшенный войлок, который вешают у входа и на стены), ковры (с узором кочкор мүйүз), шырдак и ала кийиз (для пола), подвески, украшенные вышивкой.', 'reviewed'),
  ('culture_item', 'boz-uy-ichki-jasalga', 'ru', 'modern_status', 'Хотя каркас у всех боз үй одинаков, убранство каждого неповторимо — в нём отражаются мастерство и вкус каждой семьи.', 'reviewed'),
  ('culture_item', 'boz-uy-ak-orgoo', 'ru', 'title', 'Ак өргөө', 'reviewed'),
  ('culture_item', 'boz-uy-ak-orgoo', 'ru', 'cultural_meaning', 'Ак өргөө — нарядный просторный боз үй; от обычного жилья отличается белизной, размером и красотой. Самый маленький — «алты канат» (шесть звеньев), большой — «он эки канат» (двенадцать звеньев; канат — одно звено кереге). При его строительстве не используются материалы для разведения огня и некоторые полосы войлока. Внутри есть круглая опора «тегирич», снаружи его украшает декор «кылдыраач»; самая узорчатая часть называется «ак сарай».', 'reviewed'),
  ('culture_item', 'boz-uy-ak-orgoo', 'ru', 'when_used', 'На праздниках, на мероприятиях вроде «Дня чабанов», в местах отдыха и при встрече почётных гостей; ставился отдельно от других жилищ, на высоком обособленном месте.', 'reviewed'),
  ('culture_item', 'boz-uy-ak-orgoo', 'ru', 'traditional_method', 'Строят вместе опытные мастера и специалисты.', 'reviewed'),
  ('culture_item', 'boz-uy-ak-orgoo', 'ru', 'modern_status', 'Кыргызские боз үй показывали на международных выставках в Германии, Индии, Канаде, Сирии, Турции, Алжире, Швейцарии и Монголии.', 'reviewed'),
  ('culture_item', 'oymo-overview', 'en', 'title', 'Kyrgyz ornament (oymo)', 'reviewed'),
  ('culture_item', 'oymo-overview', 'en', 'origin', 'Oyum (oymo) is the pattern, design and form used across every kind of Kyrgyz decorative art.', 'reviewed'),
  ('culture_item', 'oymo-overview', 'en', 'history', 'Kyrgyz women created many variations of the same motif and contributed greatly to the development and variety of these patterns.', 'reviewed'),
  ('culture_item', 'oymo-overview', 'en', 'cultural_meaning', 'Each pattern has its own meaning: "müyüz" (a livestock horn), "karga tyrmak" (a crow''s claw), "kyyal" (forms born of imagination), "jalbyrak" (a leaf), "gül" (a flower), and images of nature such as the sun, the moon and water carry symbolic meaning.', 'reviewed'),
  ('culture_item', 'oymo-overview', 'en', 'objects_used', 'Felt (ala kiyiz, shyrdak, tush kiyiz), leather goods (köökör, könök, terdik), wooden objects, silver and copper jewelry, embroidery.', 'reviewed'),
  ('culture_item', 'oymo-overview', 'en', 'fun_facts', 'Oymo is not only decoration: each element is seen as a sign with its own meaning within a whole system of symbols.', 'reviewed'),
  ('culture_item', 'shyrdak-craft', 'en', 'title', 'Shyrdak', 'reviewed'),
  ('culture_item', 'shyrdak-craft', 'en', 'alt_names', 'Shyrymal, törböljün, oymo teke, obodo, tür kiyiz (regional names)', 'reviewed'),
  ('culture_item', 'shyrdak-craft', 'en', 'origin', 'One of the felt items of the Kyrgyz and Mongolian peoples with the most complex making process; in Mongolian it is called "shirdeg".', 'reviewed'),
  ('culture_item', 'shyrdak-craft', 'en', 'history', 'In 2012 the traditional Kyrgyz art of making shyrdak and ala kiyiz was added to UNESCO''s Intangible Cultural Heritage list.', 'reviewed'),
  ('culture_item', 'shyrdak-craft', 'en', 'traditional_method', 'The standard size is 2×4 metres. Two layers of felt in contrasting colours are laid one on top of the other, the pattern is drawn, and both are cut at the same time with a sharp tool; the cut pieces are then swapped and sewn together, giving a positive-negative design. The stitching technique is called "shyryk", which is where the name "shyrdak" comes from.', 'reviewed'),
  ('culture_item', 'shyrdak-craft', 'en', 'modern_status', 'Today aniline dyes are used instead of natural ones (uu tamyry, indigo, isparak).', 'reviewed'),
  ('culture_item', 'shyrdak-craft', 'en', 'fun_facts', 'The patterns most often show parts of animals: a dog''s tail, a mountain goat''s horns, a bird''s claws. The edges must always finish in white and black - this stands for the snowy peaks of the Kyrgyz mountains. A shyrdak made of good felt and stored properly can last up to a hundred years.', 'reviewed'),
  ('culture_item', 'boz-uy-overview', 'en', 'title', 'Boz üy', 'reviewed'),
  ('culture_item', 'boz-uy-overview', 'en', 'origin', 'A dwelling that grew out of ancient nomadic life: quick to put up and take down, and carried on pack animals.', 'reviewed'),
  ('culture_item', 'boz-uy-overview', 'en', 'history', 'The main traditional home of the Kyrgyz - a nomadic dwelling with a wooden frame covered in felt. Its form has stayed unchanged for centuries.', 'reviewed'),
  ('culture_item', 'boz-uy-overview', 'en', 'cultural_meaning', 'The tunduk is a symbol of Kyrgyz national identity - its image appears on the state flag of Kyrgyzstan.', 'reviewed'),
  ('culture_item', 'boz-uy-overview', 'en', 'traditional_method', 'It is built in order: first the kerege is spread out and set up, then the uuk are tied to the top edge of the kerege by their pointed ends, the tunduk is raised with poles and the ends of the uuk are fitted into it, and after that the chiy, the felt covers and the door are hung.', 'reviewed'),
  ('culture_item', 'boz-uy-overview', 'en', 'objects_used', 'Kerege (wall frame), uuk (roof poles), tunduk (the ring at the top of the roof), bosogo (door frame), kaalga (door).', 'reviewed'),
  ('culture_item', 'oymo-umai-ene', 'en', 'title', 'Umai Ene', 'reviewed'),
  ('culture_item', 'oymo-umai-ene', 'en', 'origin', 'Umai Ene is the sacred mother goddess in the ancient beliefs of the Turkic peoples, seen as the protector of children and of women in childbirth.', 'reviewed'),
  ('culture_item', 'oymo-umai-ene', 'en', 'cultural_meaning', 'The Umai Ene pattern is a sacred sign of the Turkic peoples that carries the image of the ancient goddess. Among the Kyrgyz and other nomadic peoples of Central Asia it stands for the feminine principle, a mother''s nobility, and the protection of children and the home.', 'reviewed'),
  ('culture_item', 'oymo-umai-ene', 'en', 'fun_facts', 'By tradition this sign was embroidered on children''s clothes and hats (for example on a child''s ak kalpak), in the belief that it protected them from illness and evil forces. There is also a belief that a baby smiling in its sleep means Umai Ene is near.', 'reviewed'),
  ('culture_item', 'oymo-kochkor-muyuz', 'en', 'title', 'Kochkor müyüz', 'reviewed'),
  ('culture_item', 'oymo-kochkor-muyuz', 'en', 'cultural_meaning', 'It stands for the livestock of the owner and of the people living on the jailoo. No pattern is made without the kochkor müyüz. It is this element that sets Kyrgyz ornament apart from that of other peoples.', 'reviewed'),
  ('culture_item', 'oymo-kaz-moyun', 'en', 'title', 'Kaz moyun', 'reviewed'),
  ('culture_item', 'oymo-kaz-moyun', 'en', 'cultural_meaning', 'A pattern shaped like a goose''s neck.', 'reviewed'),
  ('culture_item', 'shyrdak-at-bashy', 'en', 'title', 'At-Bashy - home of the shyrdak', 'reviewed'),
  ('culture_item', 'shyrdak-at-bashy', 'en', 'origin', 'At-Bashy District in Naryn Region is recognised as the home of the shyrdak craft.', 'reviewed'),
  ('culture_item', 'shyrdak-at-bashy', 'en', 'history', 'The craft, which had begun to be forgotten, revived after UNESCO''s recognition in 2012. The "Altyn Kazan" (Golden Cauldron Herders) association was set up in At-Bashy, where some 60-70 experienced craftswomen work.', 'reviewed'),
  ('culture_item', 'shyrdak-at-bashy', 'en', 'cultural_meaning', 'A shyrdak by Janyiyl, a craftswoman from At-Bashy, was exhibited at a central museum in Great Britain - an example of the Kyrgyz shyrdak''s international recognition.', 'reviewed'),
  ('culture_item', 'shyrdak-at-bashy', 'en', 'fun_facts', 'More than 1,500 shyrdaks and over 500 craftswomen took part in the annual festival in At-Bashy; winning pieces receive cash prizes and are handed over to national museums.', 'reviewed'),
  ('culture_item', 'horse-overview', 'en', 'title', 'Horse culture', 'reviewed'),
  ('culture_item', 'horse-overview', 'en', 'origin', 'It comes from nomadic life: for the Kyrgyz the horse was not only transport but the basis of the household, of war, of games and of family tradition.', 'reviewed'),
  ('culture_item', 'horse-overview', 'en', 'history', 'The ancestors of the Kyrgyz are thought to have begun raising horses about four thousand years ago. For centuries, moving camp, going up to the jailoo and coming down to the winter quarters were all bound up with the horse.', 'reviewed'),
  ('culture_item', 'horse-overview', 'en', 'cultural_meaning', 'It is not for nothing that the Kyrgyz say "At - adamdyn kanaty" ("The horse is a person''s wings"). The horse is a symbol of wealth, freedom and honour; giving a horse is the highest mark of respect.', 'reviewed'),
  ('culture_item', 'horse-overview', 'en', 'when_used', 'All year round: when moving camp, on the jailoo, at weddings, at memorial feasts (ash) and in national games.', 'reviewed'),
  ('culture_item', 'horse-overview', 'en', 'traditional_method', 'Horse-keeping passed from father to son: tethering, grazing, watering, combing the mane and tail, fattening gradually - each done at its own time and by its own rules. Children were first put on a horse at 3-5 years old, and by 5-6 they rode on their own.', 'reviewed'),
  ('culture_item', 'horse-overview', 'en', 'who_participates', 'The whole family and community; the herder, the rider, the groom.', 'reviewed'),
  ('culture_item', 'horse-overview', 'en', 'objects_used', 'Eer (saddle), jügön (bridle), oozduk (bit), üzöngü (stirrup), kömöldürük (breast strap), kuyushkan (crupper), terdik (saddle cloth), kamchy (whip).', 'reviewed'),
  ('culture_item', 'horse-overview', 'en', 'modern_status', 'Horse breeding continues in Kyrgyzstan today; the national horse games are supported at state level and shown at the World Nomad Games.', 'reviewed'),
  ('culture_item', 'horse-overview', 'en', 'fun_facts', 'The Kyrgyz language has hundreds of words for horses: a separate word is used depending on age, coat colour, gait and temperament.', 'reviewed'),
  ('culture_item', 'horse-jylky', 'en', 'title', 'The Kyrgyz horse', 'reviewed'),
  ('culture_item', 'horse-jylky', 'en', 'alt_names', 'Kyrgyz aty', 'reviewed'),
  ('culture_item', 'horse-jylky', 'en', 'origin', 'A breed descended from the horses of the ancient Kyrgyz and adapted to mountain and steppe conditions. Mongolian and eastern breeds also had an influence.', 'reviewed'),
  ('culture_item', 'horse-jylky', 'en', 'history', 'At the end of the 19th century there were some 4 million Kyrgyz horses between the Urals and the Altai. In the Soviet period (from the 1930s) they were crossed with English and Don breeds to produce the "new Kyrgyz breed".', 'reviewed'),
  ('culture_item', 'horse-jylky', 'en', 'cultural_meaning', 'The Kyrgyz horse is the animal that kept the people alive: its meat, milk (kymyz), hide and strength were all used.', 'reviewed'),
  ('culture_item', 'horse-jylky', 'en', 'modern_status', 'The breed is being preserved; French researchers describe the Kyrgyz horse as one of the oldest breeds in the world, and work to preserve it is under way.', 'reviewed'),
  ('culture_item', 'horse-jylky', 'en', 'fun_facts', 'Average height is 137 cm. Its hooves are so strong that it needs no shoeing even on long journeys. It grazes on pasture all year round and can get through the winter on little hay. Many are natural amblers.', 'reviewed'),
  ('culture_item', 'horse-eer', 'en', 'title', 'Saddle and horse gear', 'reviewed'),
  ('culture_item', 'horse-eer', 'en', 'origin', 'In nomadic life horse gear was needed every day, so each part of it developed as a craft of its own.', 'reviewed'),
  ('culture_item', 'horse-eer', 'en', 'history', 'Carving a saddle from wood, working leather and inlaying silver are each separate crafts. Kyrgyz saddles from the 19th century are kept in museums.', 'reviewed'),
  ('culture_item', 'horse-eer', 'en', 'cultural_meaning', 'A saddle is not just an object but something that shows its owner''s standing and taste. A decorated saddle and gear were brought out for weddings, for honoured guests and for races.', 'reviewed'),
  ('culture_item', 'horse-eer', 'en', 'when_used', 'Every day for riding, and also at weddings, races and as a gift of honour.', 'reviewed'),
  ('culture_item', 'horse-eer', 'en', 'traditional_method', 'The saddle frame is carved from wood and covered with leather; patterns are applied and it is decorated with silver or copper. The terdik is placed between the horse and the saddle to protect the horse''s back.', 'reviewed'),
  ('culture_item', 'horse-eer', 'en', 'objects_used', 'Eer (wooden saddle frame), terdik (saddle cloth), köpchük (saddle cushion), üzöngü (stirrup), jügön (bridle), oozduk (bit), chylbyr (lead rein), kömöldürük (breast strap), kuyushkan (crupper), kamchy (whip).', 'reviewed'),
  ('culture_item', 'horse-eer', 'en', 'modern_status', 'The traditional craft of saddle-making is still kept alive by craftsmen; it is widely used in national games and at ethno-festivals.', 'reviewed'),
  ('culture_item', 'horse-eer', 'en', 'fun_facts', 'A decorated saddle with full gear was once also given as part of a bride''s dowry.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'en', 'title', 'Kok Boru', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'en', 'alt_names', 'Ulak tartysh', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'en', 'origin', 'According to the ethnographer G. N. Simakov: after the Kyrgyz had run down a wolf in deep snow on fast horses, they would playfully snatch the wolf''s body from one another - and the game took shape from this.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'en', 'history', 'Its modern unified rules were developed in 1996 by the film director Bolot Shamshiev. The International Kok Boru Federation was founded in Bishkek on 9 November 2001. In December 2017 the game was added to UNESCO''s Intangible Cultural Heritage list.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'en', 'cultural_meaning', 'Kok Boru is a symbol of courage, endurance and team unity - the game in which the unity of horse and rider shows most clearly.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'en', 'when_used', 'At weddings, memorial feasts (ash), national holidays and the World Nomad Games.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'en', 'traditional_method', 'The field is 200×70 metres, with a round goal called the "tai kazan" at each end. Each team has 8-12 riders, with four playing at a time. A game has three 20-minute periods. Riders must take the ulak from the ground or from an opponent and put it into their own team''s tai kazan. Striking with a hand, a foot or a whip, grabbing the reins, and rearing a horse are forbidden.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'en', 'who_participates', 'The riders of two teams; referees, and the village community as spectators.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'en', 'objects_used', 'The ulak (the body of a young goat or a goat), horses, saddle and gear, the tai kazan.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'en', 'modern_status', 'A national sport of Kyrgyzstan; at the World Nomad Games Kyrgyzstan became champion in 2014, 2016, 2018, 2022 and 2024.', 'reviewed'),
  ('culture_item', 'horse-kok-boru', 'en', 'fun_facts', 'After the game kuurdak is made from the ulak''s meat; people hold a belief that "there is healing in that meat".', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'en', 'title', 'At chabysh', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'en', 'origin', 'The most ancient race of nomadic life, testing a horse''s strength and endurance.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'en', 'history', 'At chabysh was always one of the main parts of a wedding and a memorial feast (ash); at a large ash the top prize was livestock "toguz toguz" - nine times nine animals.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'en', 'cultural_meaning', 'At chabysh is a matter of family and clan honour. Both the owner of a prize-winning horse and its rider are celebrated among the people.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'en', 'when_used', 'At weddings, memorial feasts (ash) and national holidays.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'en', 'traditional_method', 'The distance ranges from 1,200 metres to 50 kilometres. Riders are usually light boys aged 8-14. Before the celebration the horse is specially brought "into condition": excess fat is taken off, it is sweated out and hardened. The first horse to reach the finish wins.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'en', 'who_participates', 'Boy riders; the horse''s owner, the groom and the whole community.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'en', 'objects_used', 'A race horse, a light saddle, a whip (kamchy).', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'en', 'modern_status', 'It is still held today at hippodromes and village festivals; safety rules have been tightened and riders are required to wear helmets and protective clothing.', 'reviewed'),
  ('culture_item', 'horse-at-chabysh', 'en', 'fun_facts', 'Spending months specially preparing a horse for a race is called "at tapka keltirüü" - it is valued as an art of its own.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'en', 'title', 'Kyz Kuumai', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'en', 'origin', 'A horse game that grew out of the tradition of young people meeting and competing with each other.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'en', 'history', 'Played at weddings since long ago; today it is part of the national sports classification.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'en', 'cultural_meaning', 'Kyz Kuumai also shows a girl''s riding skill: a Kyrgyz girl was expected to be as good a rider as any young man.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'en', 'when_used', 'At weddings, national holidays and festivities.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'en', 'traditional_method', 'A girl and a young man set off from a marked line. The girl rides ahead and the young man tries to catch her. If he catches her, he wins; if he fails, on the way back the girl chases him, lashing him with her whip.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'en', 'who_participates', 'A girl and a young man; the whole community as spectators.', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'en', 'objects_used', 'Two horses, a whip (kamchy).', 'reviewed'),
  ('culture_item', 'horse-kyz-kuumai', 'en', 'modern_status', 'Shown as a national game at festivals and at the World Nomad Games.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'en', 'title', 'Oodarysh', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'en', 'alt_names', 'Engish', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'en', 'origin', 'It is thought to come from military training: a mounted warrior learned to throw an opponent from the saddle.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'en', 'history', 'One of the ancient Kyrgyz games; today an official national sport.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'en', 'cultural_meaning', 'Oodarysh tests not only strength but the unity of horse and rider and their balance.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'en', 'when_used', 'At weddings, memorial feasts (ash) and national holidays.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'en', 'traditional_method', 'Two mounted riders wrestle, each trying to pull the other out of the saddle. Striking, hitting the horse and some holds are forbidden; bouts are divided by time and weight categories.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'en', 'who_participates', 'Two men; referees and spectators.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'en', 'objects_used', 'Horse, saddle and gear, protective clothing.', 'reviewed'),
  ('culture_item', 'horse-oodarysh', 'en', 'modern_status', 'Part of the national sports classification; included in the programme of the World Nomad Games.', 'reviewed'),
  ('culture_item', 'shyrdak-tustor', 'en', 'title', 'The meaning of colours in a shyrdak', 'reviewed'),
  ('culture_item', 'shyrdak-tustor', 'en', 'cultural_meaning', 'White is a sign of purity, holiness and happiness, linked with newborns and the elderly. Red is a sign of blood, strength, happiness, fate, love and fire; it stands for life in full bloom (around the age of 40) and, often paired with green, expresses the abundance of summer. Blue is Tengri''s sacred colour and stands for the sky and the cosmos. Yellow stands for wealth, power and the distant steppe, but is not used on its own - because it is also linked with illness and withering, it is mostly used to mark the edge of a pattern. Green stands for youth and summer and appears in leaf and branch patterns. Black stands for the earth, strength and honour, but in traditional understanding it is more often linked with negative meanings (grief, a flaw, poverty); in a positive sense it was used only to describe beauty, such as eyes and hair.', 'reviewed'),
  ('culture_item', 'shyrdak-tustor', 'en', 'fun_facts', 'Craftswomen chose the colours for a shyrdak not at random but with symbolic intent: each combination of colours reflected a particular season or stage of life.', 'reviewed'),
  ('culture_item', 'boz-uy-tunduk', 'en', 'title', 'Tunduk', 'reviewed'),
  ('culture_item', 'boz-uy-tunduk', 'en', 'cultural_meaning', 'The round smoke opening at the top of the boz üy''s roof - the most sacred part of the home. It has two parts: the alkak (the outer ring) and the chamgarak (the crossed lattice inside the alkak). Depending on the size of the home, the alkak has 60, 70 or 80 holes, into which the ends of the uuk are fitted and fixed.', 'reviewed'),
  ('culture_item', 'boz-uy-tunduk', 'en', 'traditional_method', 'The alkak is made from thick willow or birch: the wood is steamed, bent and fitted to size; the two parts are built by overlapping one on the other.', 'reviewed'),
  ('culture_item', 'boz-uy-tunduk', 'en', 'modern_status', 'A tunduk is shown at the centre of the state flag of Kyrgyzstan - one of the most recognisable symbols of national identity.', 'reviewed'),
  ('culture_item', 'boz-uy-tunduk', 'en', 'fun_facts', 'Curses and blessings linked to the tunduk have survived: as an ill wish people said "tündügüng tüshsün" ("may your tunduk fall" - may your family break apart), and as a blessing "tündügüngdön tütün üzülbösün" ("may the smoke from your tunduk never stop" - may your family go on for ever).', 'reviewed'),
  ('culture_item', 'boz-uy-karkas', 'en', 'title', 'The wooden frame', 'reviewed'),
  ('culture_item', 'boz-uy-karkas', 'en', 'alt_names', 'Kerege, uuk', 'reviewed'),
  ('culture_item', 'boz-uy-karkas', 'en', 'cultural_meaning', 'The wooden frame of a boz üy has three main parts: the kerege (the lattice frame that serves as the wall), the uuk (the roof poles running from the kerege up to the tunduk) and the tunduk. The kerege is the more complex to make: the wood is steamed and bent, the laths are set 18-20 cm apart and tied into a lattice with strips of worked leather (kök); the joints connecting the parts are called "sakanak". The uuk are also steamed, their length measured exactly, and their ends shaped so they fit precisely into the tunduk''s holes.', 'reviewed'),
  ('culture_item', 'boz-uy-karkas', 'en', 'traditional_method', 'Experienced craftsmen built this wooden frame in about 25 days; a finished frame can serve for about 25 years despite constant moving.', 'reviewed'),
  ('culture_item', 'boz-uy-karkas', 'en', 'objects_used', 'Kerege (wall frame), uuk (roof poles), tunduk, bosogo (door frame).', 'reviewed'),
  ('culture_item', 'boz-uy-kiyiz-jabuu', 'en', 'title', 'The felt covers', 'reviewed'),
  ('culture_item', 'boz-uy-kiyiz-jabuu', 'en', 'alt_names', 'Tuurduk, üzük', 'reviewed'),
  ('culture_item', 'boz-uy-kiyiz-jabuu', 'en', 'cultural_meaning', 'Once the wooden frame is ready, it is covered with felt: the tuurduk (the felt covering the kerege, with its "jabyk bashy" facing inward), the üzük (the large front and back pieces - the "narrow" part near the tunduk keeps the home cool, while the "wide" lower part is suited to the heat of spring and summer), plus the door cover and the tunduk cover. The edges of these felts are decorated with embroidery.', 'reviewed'),
  ('culture_item', 'boz-uy-kiyiz-jabuu', 'en', 'when_used', 'When moving camp - each time the home is rebuilt at a new site.', 'reviewed'),
  ('culture_item', 'boz-uy-kiyiz-jabuu', 'en', 'traditional_method', 'Covering the frame with felt takes the combined strength of several people - most often it was done by women.', 'reviewed'),
  ('culture_item', 'boz-uy-kiyiz-jabuu', 'en', 'objects_used', 'Felt pressed from sheep''s wool, chiy (a mat woven from chiy grass stems that lines the walls).', 'reviewed'),
  ('culture_item', 'boz-uy-ichki-jasalga', 'en', 'title', 'The interior', 'reviewed'),
  ('culture_item', 'boz-uy-ichki-jasalga', 'en', 'cultural_meaning', 'The inside of a boz üy is divided by strict rules: the left side (the men''s side) is where the saddle and gear and hunting equipment are kept; the right side (the women''s side) is the kitchen and the women''s working area; in the centre are the hearth and the chests beside it; and the most honoured place behind the hearth is called the "tör" and is kept for the head of the family or a respected guest.', 'reviewed'),
  ('culture_item', 'boz-uy-ichki-jasalga', 'en', 'objects_used', 'Tush kiyiz (decorated felt hung by the door and on the walls), carpets (with the kochkor müyüz pattern), shyrdak and ala kiyiz (laid on the floor), hangings decorated with embroidery.', 'reviewed'),
  ('culture_item', 'boz-uy-ichki-jasalga', 'en', 'modern_status', 'Although every boz üy has the same frame, each interior is unique - it reflects each family''s own skill and taste.', 'reviewed'),
  ('culture_item', 'boz-uy-ak-orgoo', 'en', 'title', 'Ak örgöö', 'reviewed'),
  ('culture_item', 'boz-uy-ak-orgoo', 'en', 'cultural_meaning', 'An ak örgöö is a decorated, spacious boz üy; it stands out from an ordinary home by its whiteness, size and beauty. The smallest is "alty kanat" (six sections) and a large one "on eki kanat" (twelve sections; a kanat is one section of the kerege). Materials for making fire and some felt strips are not used in building it. Inside there is a round support called the "tegirich", and the outside is decorated with an ornament called "kyldyraach"; the most ornate part is called the "ak saray".', 'reviewed'),
  ('culture_item', 'boz-uy-ak-orgoo', 'en', 'when_used', 'At celebrations, at events such as "Shepherds'' Day", at places of rest and when receiving honoured guests; it was set apart from other homes, on a high, separate spot.', 'reviewed'),
  ('culture_item', 'boz-uy-ak-orgoo', 'en', 'traditional_method', 'It is built by skilled craftsmen and specialists working together.', 'reviewed'),
  ('culture_item', 'boz-uy-ak-orgoo', 'en', 'modern_status', 'Kyrgyz boz üys have been shown at international exhibitions in Germany, India, Canada, Syria, Turkey, Algeria, Switzerland and Mongolia.', 'reviewed'),
  ('explore_region', 'chuy', 'ru', 'fact.0', 'Крупные города: Токмок, Кант, Кара-Балта.', 'reviewed'),
  ('explore_region', 'chuy', 'ru', 'fact.1', 'Город Бишкек имеет отдельный республиканский статус, поэтому не входит в состав области.', 'reviewed'),
  ('explore_region', 'chuy', 'en', 'fact.0', 'Its main towns are Tokmok, Kant and Kara-Balta.', 'reviewed'),
  ('explore_region', 'chuy', 'en', 'fact.1', 'The city of Bishkek has its own national-level status, so it is not part of the region.', 'reviewed'),
  ('explore_region', 'naryn', 'ru', 'fact.0', '95% территории области расположено выше 1000 метров над уровнем моря.', 'reviewed'),
  ('explore_region', 'naryn', 'ru', 'fact.1', 'Родина высокогорных озёр — Сон-Куль, Кол-Суу, Чатыр-Куль.', 'reviewed'),
  ('explore_region', 'naryn', 'en', 'fact.0', '95% of the region lies more than 1,000 metres above sea level.', 'reviewed'),
  ('explore_region', 'naryn', 'en', 'fact.1', 'It is home to high mountain lakes such as Son-Köl, Kol-Suu and Chatyr-Köl.', 'reviewed'),
  ('explore_region', 'osh', 'ru', 'fact.0', 'Расположен в восточной части Ферганской долины, у подножия Алайских гор.', 'reviewed'),
  ('explore_region', 'osh', 'ru', 'fact.1', 'Второй по величине город Кыргызстана.', 'reviewed'),
  ('explore_region', 'osh', 'en', 'fact.0', 'It lies in the eastern part of the Fergana Valley, at the foot of the Alay mountains.', 'reviewed'),
  ('explore_region', 'osh', 'en', 'fact.1', 'It is the second-largest city in Kyrgyzstan.', 'reviewed'),
  ('explore_region', 'jalal-abad', 'ru', 'fact.0', 'На основе минеральных источников здесь развились курорты.', 'reviewed'),
  ('explore_region', 'jalal-abad', 'ru', 'fact.1', 'В этой области находятся ореховый лес Арсланбоб и Сары-Челекский биосферный заповедник.', 'reviewed'),
  ('explore_region', 'jalal-abad', 'en', 'fact.0', 'Resorts have grown up around its mineral springs.', 'reviewed'),
  ('explore_region', 'jalal-abad', 'en', 'fact.1', 'The Arslanbob walnut forest and the Sary-Chelek Biosphere Reserve are in this region.', 'reviewed'),
  ('explore_region', 'suusamyr', 'ru', 'fact.0', 'Между хребтами Кыргызский Ала-Тоо, Суусамыр и Джумгал, на высоте 2000–3200 метров.', 'reviewed'),
  ('explore_region', 'suusamyr', 'ru', 'fact.1', 'Главное пастбище для скота, пригоняемого из Чуйской, Таласской и Кетмень-Тюбинской долин.', 'reviewed'),
  ('explore_region', 'suusamyr', 'en', 'fact.0', 'It lies between the Kyrgyz Ala-Too, Suusamyr and Jumgal ranges, at 2,000-3,200 metres.', 'reviewed'),
  ('explore_region', 'suusamyr', 'en', 'fact.1', 'It is the main pasture for livestock brought from the Chüy, Talas and Ketmen-Töbö valleys.', 'reviewed'),
  ('explore_region', 'arslanbob', 'ru', 'fact.0', 'Расположен в Джалал-Абадской области, в долине Арстанбап.', 'reviewed'),
  ('explore_region', 'arslanbob', 'ru', 'fact.1', 'Возраст некоторых ореховых деревьев превышает тысячу лет.', 'reviewed'),
  ('explore_region', 'arslanbob', 'en', 'fact.0', 'It lies in Jalal-Abad Region, in the Arstanbap valley.', 'reviewed'),
  ('explore_region', 'arslanbob', 'en', 'fact.1', 'Some of its walnut trees are more than a thousand years old.', 'reviewed')
